#define RAM_SIZE 0x200000u
#define BASE 0x800b5788u
#define END 0x80131ef0u
#define WORDS ((END-BASE)/4)
typedef struct{const uint8_t*p,*e;}R;typedef struct{uint32_t pc;uint64_t frames,insns;}Hit;
static uint8_t*dom[4],map[WORDS];static uint32_t dsz[4];static uint64_t counts[WORDS];static uint32_t flow_frames[WORDS];
static uint64_t records,checks,mismatches,flow_items,flow_insns;static int saw_clear,saw_386,trio_have;static unsigned tri_min[3]={255,255,255},tri_max[3];
static const uint32_t keys[]={0x8003e7c0,0x800b6250,0x800b6b18,0x800b6b20,0x800b6b28,0x800b6b3c,0x800b6b44,0x800b6d68,0x800b704c,0x800b7400,0x800b7418,0x800b7438,0x800b7464};
static const uint64_t expected[]={1,1,0,0,72,0,0,1,1,45,1,70,1};static Hit hits[sizeof keys/sizeof keys[0]];
static void die(const char*s){fprintf(stderr,"e15_capsule: %s\n",s);exit(1);}static const uint8_t*take(R*r,size_t n){if((size_t)(r->e-r->p)<n)die("truncated record");const uint8_t*p=r->p;r->p+=n;return p;}
static uint8_t u8(R*r){return*take(r,1);}static uint16_t u16(R*r){const uint8_t*p=take(r,2);return(uint16_t)(p[0]|p[1]<<8);}static uint32_t u32(R*r){const uint8_t*p=take(r,4);return(uint32_t)p[0]|(uint32_t)p[1]<<8|(uint32_t)p[2]<<16|(uint32_t)p[3]<<24;}static uint64_t u64(R*r){uint64_t a=u32(r),b=u32(r);return a|(b<<32);}static int32_t s32(const uint8_t*p){return(int32_t)((uint32_t)p[0]|(uint32_t)p[1]<<8|(uint32_t)p[2]<<16|(uint32_t)p[3]<<24);}static int16_t s16(const uint8_t*p){return(int16_t)(p[0]|p[1]<<8);}
static uint8_t*unpack(const char*path,size_t*n){FILE*f=fopen(path,"rb");long z;uint8_t*in,*out;unsigned long long oz;size_t got;if(!f){perror(path);exit(2);}fseek(f,0,SEEK_END);z=ftell(f);rewind(f);if(z<=0)die("chunk size");in=malloc((size_t)z);if(!in||fread(in,1,(size_t)z,f)!=(size_t)z)die("chunk read");fclose(f);oz=ZSTD_getFrameContentSize(in,(size_t)z);if(oz==ZSTD_CONTENTSIZE_ERROR||oz==ZSTD_CONTENTSIZE_UNKNOWN||oz>SIZE_MAX)die("zstd size");out=malloc((size_t)oz);if(!out)die("zstd allocation");got=ZSTD_decompress(out,(size_t)oz,in,(size_t)z);free(in);if(ZSTD_isError(got)||got!=(size_t)oz)die("zstd decode");*n=got;return out;}
static int shaok(const uint8_t*p,size_t n,const uint8_t*want){uint8_t got[32];size_t gn=0;if(!EVP_Q_digest(NULL,"SHA256",NULL,p,n,got,&gn)||gn!=32)die("sha256");return!memcmp(got,want,32);}
static void add_flow(uint32_t pc,uint32_t n){flow_items++;flow_insns+=n;for(size_t i=0;i<sizeof keys/sizeof keys[0];i++)if(pc==keys[i]){hits[i].pc=pc;hits[i].frames++;hits[i].insns+=n;}if(pc>=BASE&&pc<END&&!(pc&3u)){size_t i=(pc-BASE)/4;counts[i]+=n;flow_frames[i]++;}}
static void chunk(const char*path,int*have,int32_t*pf,int16_t*pl){size_t n;uint8_t*raw=unpack(path,&n);R r={raw,raw+n};uint32_t ver,nregs;if(memcmp(take(&r,8),"DSTCAP01",8))die("magic");ver=u32(&r);if(ver<1||ver>2)die("version");(void)u32(&r);(void)u64(&r);nregs=u32(&r);for(uint32_t i=0;i<nregs;i++){uint16_t z=u16(&r);(void)take(&r,z);}while(r.p<r.e){uint32_t movie;uint8_t*ram=NULL;if(u8(&r)!=1)die("tag");(void)u64(&r);(void)u64(&r);movie=u32(&r);(void)u32(&r);(void)u32(&r);for(uint32_t i=0;i<nregs;i++)(void)u32(&r);for(unsigned k=0;k<3;k++){uint32_t id=u32(&r),sz=u32(&r),runs=u32(&r);const uint8_t*want=take(&r,32);if(id<1||id>3)die("domain id");if(!dom[id]){dom[id]=calloc(1,sz);dsz[id]=sz;}if(!dom[id]||dsz[id]!=sz)die("domain shape");for(uint32_t j=0;j<runs;j++){uint32_t o=u32(&r),len=u32(&r);const uint8_t*src=take(&r,len);if(o>sz||len>sz-o)die("patch range");memcpy(dom[id]+o,src,len);}checks++;if(!shaok(dom[id],sz,want))mismatches++;}for(unsigned id=1;id<=3;id++)if(dsz[id]==RAM_SIZE)ram=dom[id];if(!ram)die("RAM absent");for(unsigned i=0;i<3;i++){static const uint32_t off[]={0x9b888,0x9b889,0x9b88a};unsigned v=ram[off[i]];if(v<tri_min[i])tri_min[i]=v;if(v>tri_max[i])tri_max[i]=v;}trio_have=1;int32_t flag=s32(ram+0xcac10);int16_t lim=s16(ram+0x131eee);if(*have){if(*pf!=0&&flag==0&&movie==86)saw_clear=1;if(*pl==0&&lim==386&&movie==183)saw_386=1;}else *have=1;*pf=flag;*pl=lim;uint64_t nf=u64(&r);for(uint64_t i=0;i<nf;i++){uint32_t pc=u32(&r),c;if(ver==2){c=u32(&r);(void)u64(&r);}else{uint64_t w=u64(&r);c=w>UINT32_MAX?UINT32_MAX:(uint32_t)w;}add_flow(pc,c);}records++;}free(raw);}
int main(int ac,char**av){FILE*f;unsigned a;char pat[4096];glob_t g={0};int have=0;int32_t pf=0;int16_t pl=0;unsigned unique=0,outside=0;uint32_t min=UINT32_MAX,max=0;if(ac!=3){fprintf(stderr,"usage: %s CAPSULE_DIR MAP\n",av[0]);return 2;}f=fopen(av[2],"r");if(!f)return 2;while(fscanf(f,"%x",&a)==1)if(a>=BASE&&a<END&&!(a&3u))map[(a-BASE)/4]=1;fclose(f);if(snprintf(pat,sizeof pat,"%s/chunks/*.zst",av[1])>=(int)sizeof pat)die("path");if(glob(pat,0,NULL,&g)||!g.gl_pathc)die("no chunks");for(size_t i=0;i<g.gl_pathc;i++)chunk(g.gl_pathv[i],&have,&pf,&pl);for(size_t i=0;i<WORDS;i++)if(counts[i]){uint32_t pc=BASE+(uint32_t)i*4;unique++;if(pc<min)min=pc;if(pc>max)max=pc;if(!map[i])outside++;}for(size_t i=0;i<sizeof keys/sizeof keys[0];i++)if(hits[i].frames!=expected[i])die("key block counts");if(records!=542||checks!=1626||mismatches||flow_items!=244942||flow_insns!=25730645||unique!=412||min!=0x800b6250||max!=0x800b998c||outside||!saw_clear||!saw_386||!trio_have||tri_min[0]||tri_max[0]||tri_min[1]||tri_max[1]||tri_min[2]||tri_max[2])die("capsule evidence changed");printf("{\"records\":%"PRIu64",\"hash_checks\":%"PRIu64",\"hash_mismatches\":0,\"flow_items\":%"PRIu64",\"flow_instructions\":%"PRIu64",\"overlay_unique_pcs\":%u,\"outside_static_frontier\":0,\"frame_limit\":386,\"ending_bytes\":[0,0,0]}\n",records,checks,flow_items,flow_insns,unique);for(unsigned i=1;i<=3;i++)free(dom[i]);globfree(&g);return 0;}
